import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, "UTF-8"));
        int q = Integer.parseInt(reader.readLine().trim());
        ArrayList<Long> times = new ArrayList<>();
        ArrayList<String> services = new ArrayList<>(), levels = new ArrayList<>(), messages = new ArrayList<>();
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String line = reader.readLine();
            if (line == null) break;
            if (line.startsWith("ADD ")) {
                // The message is the rest of the line and may contain spaces.
                String[] p = line.trim().split("\\s+", 5);
                times.add(Long.parseLong(p[1]));
                services.add(p[2]);
                levels.add(p[3]);
                messages.add(p[4]);
            } else {
                String[] p = line.trim().split("\\s+");
                long a = Long.parseLong(p[1]), b = Long.parseLong(p[2]);
                String s = p[3], l = p[4], k = p[5];
                int count = 0;
                for (int i = 0; i < times.size(); i++) {
                    long time = times.get(i);
                    if (a <= time && time <= b && (s.equals("*") || s.equals(services.get(i)))
                        && (l.equals("*") || l.equals(levels.get(i)))
                        && (k.equals("*") || messages.get(i).contains(k)))
                        count++;
                }
                out.append(count).append('\n');
            }
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	q, _ := strconv.Atoi(strings.TrimSpace(lines[0]))
	type entry struct {
		time                    int
		service, level, message string
	}
	logs := []entry{}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := 1; t <= q && t < len(lines); t++ {
		line := lines[t]
		if strings.HasPrefix(line, "ADD ") {
			// The message is the rest of the line after four fields and may contain spaces.
			rest := line
			fields := make([]string, 4)
			for i := range fields {
				rest = strings.TrimLeft(rest, " \t")
				end := strings.IndexAny(rest, " \t")
				if end < 0 {
					end = len(rest)
				}
				fields[i], rest = rest[:end], rest[end:]
			}
			time, _ := strconv.Atoi(fields[1])
			logs = append(logs, entry{time, fields[2], fields[3], strings.TrimLeft(rest, " \t")})
		} else {
			p := strings.Fields(line)
			a, _ := strconv.Atoi(p[1])
			b, _ := strconv.Atoi(p[2])
			s, l, k := p[3], p[4], p[5]
			count := 0
			for _, e := range logs {
				if a <= e.time && e.time <= b && (s == "*" || s == e.service) &&
					(l == "*" || l == e.level) && (k == "*" || strings.Contains(e.message, k)) {
					count++
				}
			}
			fmt.Fprintln(w, count)
		}
	}
}
